class.description:
Controls how [method FlowGraphMermaid.serialize] writes a [FlowGraph]. The defaults write a lossless file. Turn off [member include_data_comments] for a plain diagram in documentation, which loads back only with generic nodes.
[codeblocks]
[gdscript]
var options := FlowGraphMermaidOptions.new()
options.direction = FlowGraphMermaidOptions.DIRECTION_LEFT_RIGHT
options.include_editor_data = false
var text := FlowGraphMermaid.serialize(graph, options)
[/gdscript]
[csharp]
var options = new FlowGraphMermaidOptions();
options.Direction = FlowGraphMermaidOptions.DirectionEnum.LeftRight;
options.IncludeEditorData = false;
string text = FlowGraphMermaid.Serialize(graph, options);
[/csharp]
[/codeblocks]
